begin;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAILED: %',label;end if;end$$;
create function pg_temp.reject(q text) returns void language plpgsql as $$begin begin execute q;exception when insufficient_privilege or serialization_failure or raise_exception then return;end;raise exception 'UNEXPECTEDLY ALLOWED: %',q;end$$;
select pg_temp.ok(not has_function_privilege('anon','public.set_store_picture(uuid,text,text)','execute'),'Guest mutation denied');
select pg_temp.ok((select not public and file_size_limit=262144 and allowed_mime_types=array['image/webp'] from storage.buckets where id='store-images'),'Private WebP-only bounded bucket');
insert into auth.users(id,email,raw_user_meta_data) values('f1100000-0000-4000-8000-000000000001','store1@picture.invalid','{}'),('f1100000-0000-4000-8000-000000000002','store2@picture.invalid','{}'),('f1100000-0000-4000-8000-000000000003','buyer@picture.invalid','{}');
update public.user_roles set role='supplier' where user_id in('f1100000-0000-4000-8000-000000000001','f1100000-0000-4000-8000-000000000002');
insert into public.businesses(id,owner_id,name,division,district) values('f1200000-0000-4000-8000-000000000001','f1100000-0000-4000-8000-000000000001','Synthetic store picture business','Dhaka','Dhaka'),('f1200000-0000-4000-8000-000000000002','f1100000-0000-4000-8000-000000000002','Other synthetic store','Dhaka','Dhaka');
set local request.jwt.claims='{"sub":"f1100000-0000-4000-8000-000000000001","role":"authenticated"}';set local role authenticated;
insert into storage.objects(bucket_id,name,metadata) values('store-images','f1100000-0000-4000-8000-000000000001/f1200000-0000-4000-8000-000000000001/f1300000-0000-4000-8000-000000000001.webp','{"mimetype":"image/webp","size":100}');
select public.set_store_picture('f1200000-0000-4000-8000-000000000001',null,'f1100000-0000-4000-8000-000000000001/f1200000-0000-4000-8000-000000000001/f1300000-0000-4000-8000-000000000001.webp');
select pg_temp.ok((select profile_image_path is not null from public.businesses where id='f1200000-0000-4000-8000-000000000001'),'Owner can attach uploaded picture');
select pg_temp.reject($$select public.set_store_picture('f1200000-0000-4000-8000-000000000001',null,null)$$);
select pg_temp.reject($$select public.set_store_picture('f1200000-0000-4000-8000-000000000002',null,null)$$);
select pg_temp.reject($$insert into storage.objects(bucket_id,name) values('store-images','f1100000-0000-4000-8000-000000000001/f1200000-0000-4000-8000-000000000002/f1300000-0000-4000-8000-000000000002.webp')$$);
select pg_temp.reject($$update public.businesses set profile_image_path='https://external.invalid/logo.webp' where id='f1200000-0000-4000-8000-000000000001'$$);
select pg_temp.ok(not private.unlinked_store_image('f1100000-0000-4000-8000-000000000001/f1200000-0000-4000-8000-000000000001/f1300000-0000-4000-8000-000000000001.webp'),'Current picture cannot be removed from storage');
update storage.objects set metadata='{"mimetype":"image/webp","size":200}' where bucket_id='store-images' and name like 'f1100000%';
select pg_temp.ok((select metadata->>'size'='100' from storage.objects where bucket_id='store-images' and name like 'f1100000%'),'Overwrite/update denied');
reset role;set local role anon;set local request.jwt.claims='{}';
select pg_temp.ok((select count(*)=0 from storage.objects where bucket_id='store-images' and name like 'f1100000%'),'Unpublished store hidden from guests');
reset role;
insert into public.products(id,business_id,category_id,name,description,price,moq,status) values('f1400000-0000-4000-8000-000000000001','f1200000-0000-4000-8000-000000000001',(select id from public.categories limit 1),'Synthetic picture test listing','Synthetic picture test listing only',100,10,'approved');
set local role anon;
select pg_temp.ok((select count(*)=1 from storage.objects where bucket_id='store-images' and name like 'f1100000%'),'Public eligible store picture readable');
select pg_temp.ok((select profile_image_path is not null from public.public_businesses() where id='f1200000-0000-4000-8000-000000000001'),'Public catalog includes store picture');
reset role;update public.account_statuses set status='suspended',reason='Synthetic picture test' where user_id='f1100000-0000-4000-8000-000000000001';set local role anon;
select pg_temp.ok((select count(*)=0 from storage.objects where bucket_id='store-images' and name like 'f1100000%'),'Suspension blocks fresh public signed access');
reset role;set local role authenticated;set local request.jwt.claims='{"sub":"f1100000-0000-4000-8000-000000000003","role":"authenticated"}';
select pg_temp.reject($$select public.set_store_picture('f1200000-0000-4000-8000-000000000001',null,null)$$);
select pg_temp.ok((select count(*)=0 from storage.objects where bucket_id='store-images' and name like 'f1100000%'),'Buyer cannot read hidden store picture');
set local request.jwt.claims='{"sub":"f1100000-0000-4000-8000-000000000001","role":"authenticated"}';
select public.set_store_picture('f1200000-0000-4000-8000-000000000001','f1100000-0000-4000-8000-000000000001/f1200000-0000-4000-8000-000000000001/f1300000-0000-4000-8000-000000000001.webp',null);
select pg_temp.ok(private.unlinked_store_image('f1100000-0000-4000-8000-000000000001/f1200000-0000-4000-8000-000000000001/f1300000-0000-4000-8000-000000000001.webp'),'Owner can clear picture while suspended for remediation');
reset role;
select 'Store picture authorization checks passed; all fixtures rolled back.' result;
rollback;
